package com.payshield.api; import com.payshield.service.PaymentException; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant;
@RestControllerAdvice public class GlobalExceptionHandler {@ExceptionHandler(PaymentException.class) ResponseEntity<ApiError> payment(PaymentException e){return error(e.status(),e.getMessage());}@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e){return error(400,e.getBindingResult().getFieldError().getField()+" is invalid");}@ExceptionHandler(Exception.class) ResponseEntity<ApiError> fallback(Exception e){return error(500,"Unexpected server error");}private ResponseEntity<ApiError> error(int status,String message){return ResponseEntity.status(status).body(new ApiError(Instant.now(),status,HttpStatus.valueOf(status).getReasonPhrase(),message));}}
